-- ============================================
-- LUMA — Thème 7 : LONG 3/3 x4 — Préparer une garde-robe pour un événement
-- ============================================


update scenarios set content = '{"characters": {"stylist": "le/la styliste"}, "start_node": "n1", "nodes": {"n1": {"speaker": "stylist", "text": "Welcome! I understand you have an important business trip coming up. Tell me about it.", "text_fr": "Bienvenue ! Je comprends que vous avez un voyage d''affaires important à venir. Parlez-m''en.", "choices": [{"text": "Yes, five days, mix of formal meetings and some networking dinners.", "text_fr": "Oui, cinq jours, un mélange de réunions formelles et de dîners de réseautage.", "next": "n2"}, {"text": "It''s a big conference, lots of presentations and client meetings.", "text_fr": "C''est une grande conférence, beaucoup de présentations et de réunions clients.", "next": "n2b"}]}, "n2": {"speaker": "stylist", "text": "Perfect, so we''ll need versatile pieces that work for both settings. What''s your current wardrobe like?", "text_fr": "Parfait, donc on aura besoin de pièces polyvalentes qui marchent pour les deux contextes. Votre garde-robe actuelle ressemble à quoi ?", "choices": [{"text": "Mostly casual, I don''t have much formal business wear.", "text_fr": "Surtout décontracté, j''ai pas beaucoup de tenues d''affaires formelles.", "next": "n3"}, {"text": "I have a couple suits, but nothing that feels quite right.", "text_fr": "J''ai deux trois costumes, mais rien qui semble vraiment adapté.", "next": "n3"}]}, "n2b": {"speaker": "stylist", "text": "Got it, so we need pieces that project confidence and professionalism. What''s your current wardrobe like?", "text_fr": "Compris, donc on a besoin de pièces qui projettent confiance et professionnalisme. Votre garde-robe actuelle ressemble à quoi ?", "choices": [{"text": "Pretty limited on the formal side, honestly.", "text_fr": "Assez limitée côté formel, honnêtement.", "next": "n3"}]}, "n3": {"speaker": "stylist", "text": "No worries, we''ll build from scratch then. Let''s start with a base — a solid suit color.", "text_fr": "Pas de souci, on va construire à partir de rien alors. Commençons par une base — une couleur de costume solide.", "choices": [{"text": "I''ve always liked navy, it feels safe but professional.", "text_fr": "J''ai toujours aimé le bleu marine, ça semble sûr mais professionnel.", "next": "n4"}, {"text": "I''m open to something a bit bolder, like charcoal grey.", "text_fr": "Je suis ouvert à quelque chose d''un peu plus audacieux, comme le gris anthracite.", "next": "n4"}]}, "n4": {"speaker": "stylist", "text": "Great choice, that''ll work well as your anchor piece. Now, how many shirts do you think you''ll need?", "text_fr": "Excellent choix, ça fonctionnera bien comme pièce d''ancrage. Maintenant, combien de chemises pensez-vous avoir besoin ?", "choices": [{"text": "Maybe four or five, to mix and match across the trip?", "text_fr": "Peut-être quatre ou cinq, pour mélanger et assortir pendant le voyage ?", "next": "n5"}]}, "n5": {"speaker": "stylist", "text": "Good number. Let''s pick a mix of white, light blue, and maybe one patterned option.", "text_fr": "Bon nombre. Choisissons un mélange de blanc, bleu clair, et peut-être une option à motifs.", "choices": [{"text": "That sounds versatile, I like that approach.", "text_fr": "Ça semble polyvalent, j''aime cette approche.", "next": "n6"}, {"text": "Could we skip the patterned one? I prefer to keep things simple.", "text_fr": "On pourrait éviter celle à motifs ? Je préfère garder ça simple.", "next": "n6"}]}, "n6": {"speaker": "stylist", "text": "Absolutely, simplicity works great too. Now, what about the evening dinners — more relaxed pieces?", "text_fr": "Absolument, la simplicité fonctionne bien aussi. Et pour les dîners du soir — des pièces plus décontractées ?", "choices": [{"text": "Yes, something smart-casual that still feels put together.", "text_fr": "Oui, quelque chose de smart-casual qui reste soigné.", "next": "n7"}]}, "n7": {"speaker": "stylist", "text": "A nice blazer with dark jeans or chinos could work perfectly for that.", "text_fr": "Un beau blazer avec un jean foncé ou un chino pourrait fonctionner parfaitement pour ça.", "choices": [{"text": "I love that combination, feels professional but relaxed.", "text_fr": "J''adore cette combinaison, ça semble professionnel mais détendu.", "next": "n8"}]}, "n8": {"speaker": "stylist", "text": "Perfect. Now let''s talk shoes — do you have versatile options already?", "text_fr": "Parfait. Maintenant parlons chaussures — vous avez déjà des options polyvalentes ?", "choices": [{"text": "I have one pair of black dress shoes, that''s about it.", "text_fr": "J''ai une paire de chaussures habillées noires, c''est à peu près tout.", "next": "n9"}, {"text": "Just sneakers, honestly, nothing formal.", "text_fr": "Juste des baskets, honnêtement, rien de formel.", "next": "n9"}]}, "n9": {"speaker": "stylist", "text": "Let''s add a brown pair too, gives you more flexibility with different outfits.", "text_fr": "Ajoutons aussi une paire marron, ça vous donne plus de flexibilité avec différentes tenues.", "choices": [{"text": "Good idea, I hadn''t thought about needing two colors.", "text_fr": "Bonne idée, j''avais pas pensé avoir besoin de deux couleurs.", "next": "n10"}]}, "n10": {"speaker": "stylist", "text": "Now let''s put together full outfit combinations for each day of your trip.", "text_fr": "Maintenant assemblons des combinaisons de tenues complètes pour chaque jour de votre voyage.", "choices": [{"text": "That would be so helpful, I always struggle with planning that out.", "text_fr": "Ça serait tellement utile, j''ai toujours du mal à planifier ça.", "next": "n11"}]}, "n11": {"speaker": "stylist", "text": "(Lays out five complete outfits, mixing and matching everything chosen.)", "text_fr": "(Étale cinq tenues complètes, mélangeant et assortissant tout ce qui a été choisi.)", "choices": [{"text": "This is incredible, I actually feel prepared for once.", "text_fr": "C''est incroyable, je me sens vraiment préparé pour une fois.", "next": "n12"}, {"text": "I never would have thought to combine these pieces this way.", "text_fr": "J''aurais jamais pensé combiner ces pièces de cette façon.", "next": "n12"}]}, "n12": {"speaker": "stylist", "text": "That''s exactly the goal — confidence through preparation. Any final questions?", "text_fr": "C''est exactement le but — la confiance par la préparation. Des dernières questions ?", "choices": [{"text": "Just — thank you, this whole process felt so much less overwhelming than I expected.", "text_fr": "Juste — merci, tout ce processus a semblé bien moins accablant que prévu.", "next": "end_prepared"}]}, "end_prepared": {"speaker": "stylist", "text": "That''s wonderful to hear. You''re going to feel confident and sharp on this trip!", "text_fr": "C''est merveilleux à entendre. Vous allez vous sentir confiant et impeccable pendant ce voyage !", "end": true, "ending_label": "Garde-robe complète préparée avec assurance 🧥💼✨"}}}'::jsonb, is_playable = true
where title = 'Préparer une garde-robe pour un événement'
  and theme_id = (select id from scenario_themes where position = 7 and language_id = (select id from languages where code = 'en'));
